package sohal.lld.chess.entity.playable;import sohal.lld.chess.entity.Color;import sohal.lld.chess.entity.board.Board;import sohal.lld.chess.entity.board.Cell;public class Pawn extends Piece {    public Pawn(Color color) {        super(color);    }    @Override    public boolean canMove(Board board, Cell start, Cell end) {        int rowDiff = end.getRow() - start.getRow();        int colDiff = Math.abs(end.getCol() - start.getCol());        if(this.getColor() == Color.WHITE) {            return (rowDiff == 1 && colDiff == 0) || (start.getRow() == 1 && rowDiff == 2 && colDiff == 0) ||                    (rowDiff ==1 && colDiff == 1 && board.getPiece(end.getRow(), end.getCol()) != null &&                            board.getPiece(end.getRow(), end.getCol()).getColor() == Color.BLACK);        }        else {            return (rowDiff == -1 && colDiff == 0) || (start.getRow() == 6 && rowDiff == -2 && colDiff == 0) ||                    (rowDiff == -1 && colDiff == 1 && board.getPiece(end.getRow(), end.getCol()) != null &&                            board.getPiece(end.getRow(), end.getCol()).getColor() == Color.WHITE);        }    }}